'use strict';

// MODULES //

import isnan from '@stdlib/math-base-assert-is-nan';
import incrmmeanstdev from '@stdlib/stats-incr-mmeanstdev';


// MAIN //

/**
* Returns an accumulator function which incrementally computes a moving arithmetic mean and corrected sample standard deviation, ignoring `NaN` values.
*
* @param {Collection} [out] - output array
* @param {PositiveInteger} window - window size
* @throws {TypeError} output argument must be array-like
* @throws {TypeError} window size must be a positive integer
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmmeanstdev( 3 );
*
* var v = accumulator();
* // returns null
*
* v = accumulator( 2.0 );
* // returns [ 2.0, 0.0 ]
*
* v = accumulator( NaN );
* // returns [ 2.0, 0.0 ]
*
* v = accumulator( -5.0 );
* // returns [ -1.5, ~4.95 ]
*
* v = accumulator( 3.0 );
* // returns [ 0.0, ~4.36 ]
*
* v = accumulator();
* // returns [ 0.0, ~4.36 ]
*/
function incrnanmmeanstdev( out, window ) {
	var mmeanstdev;

	if ( arguments.length === 1 ) {
		mmeanstdev = incrmmeanstdev( out );
	} else {
		mmeanstdev = incrmmeanstdev( out, window );
	}
	return accumulator;

	/**
	* If provided a value, the accumulator function returns updated accumulated values. If provided `NaN` or no value, the accumulator function returns the current accumulated values.
	*
	* @private
	* @param {number} [x] - input value
	* @returns {(ArrayLikeObject|null)} output array or null
	*/
	function accumulator( x ) {
		if ( arguments.length === 0 || isnan( x ) ) {
			return mmeanstdev();
		}
		return mmeanstdev( x );
	}
}


// EXPORTS //

export default incrnanmmeanstdev;
